public partial class RoadMapEditor {
 float propY;float propHeight=2400;float propWidth=330;string deleteId="",connectTarget="";int connectTurn,connectChange;
 void Caption(string text){GUI.Label(new Rect(0,propY,propWidth,28),text,label);propY+=29;}
 void ActionButton(string text,Action action){if(Button(0,propY,propWidth,text))action();propY+=34;}
 string Text(string name,string value,Action<string> setter){Caption(name);string next=GUI.TextField(new Rect(0,propY,propWidth,28),value??"",field);propY+=32;if(next!=(value??""))Edit(()=>setter(next));return next;}
 void Number(string name,float value,Action<float> setter,float min=-100000,float max=100000){string key=selected+":"+SelectedPoint+":"+name;string old;if(!numbers.TryGetValue(key,out old))old=value.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);Caption(name);string next=GUI.TextField(new Rect(0,propY,propWidth,28),old,field);propY+=32;if(next!=old){numbers[key]=next;float n;if(float.TryParse(next,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out n)&&!float.IsNaN(n)&&!float.IsInfinity(n)&&n>=min&&n<=max)Edit(()=>setter(n));}}
 void Toggle(string text,bool value,Action<bool> setter){bool next=GUI.Toggle(new Rect(0,propY,propWidth,28),value,text,label);propY+=30;if(next!=value)Edit(()=>setter(next));}
 void Properties(Rect rect){Fill(rect,new Color(.07f,.1f,.14f));rightScroll=GUI.BeginScrollView(rect,rightScroll,new Rect(0,0,propWidth,propHeight));propY=0;Caption(tool+" 도구 · "+Short(selected));
  if(tool=="신호")SignalProperties();else if(Facility!=null)FacilityProperties();else if(Lane!=null)LaneProperties();else Caption("지도에서 차로/시설을 선택하세요.");
  if(tool=="표지")ActionButton("지도 중앙에 안내 표지 추가",()=>AddFacility("sign"));if(tool=="노면"){foreach(var kind in new[]{"stopLine","crosswalk","line","centreLine"}){string k=kind;ActionButton("지도 중앙에 "+kind+" 추가",()=>AddFacility(k));}}
  propY+=12;Text("수정본 이름",document.name,v=>document.name=v);Caption("시험 경로 · 차로 선택 후 지정");ActionButton("선택 차로를 출발로",()=>TrialStart=selected);Caption("출발: "+Short(TrialStart));ActionButton("선택 차로를 도착으로",()=>TrialGoal=selected);Caption("도착: "+Short(TrialGoal));propHeight=Mathf.Max(2400,propY+80);GUI.EndScrollView();
 }
 void LaneProperties(){var l=Lane;Caption(l.id);Caption("교차로 "+l.ruleId+" / "+l.roadName);Toggle("비활성화 (참조 영향은 아래 확인)",l.disabled,v=>l.disabled=v);Number("운전자 기준 차로 번호",l.number,v=>l.number=(int)v,1,12);Number("차로 폭 m",l.width,v=>l.width=v,2.6f,5);Caption("허용 방향 · 출구 연결에서 선택");
  foreach(int turn in new[]{-1,0,1}){int t=turn;bool has=l.next.Any(id=>{var n=document.lanes.FirstOrDefault(e=>e.id==id);return n!=null&&n.turn==t&&n.change==0;});Toggle(t<0?"좌회전":t>0?"우회전":"직진",has,v=>{var candidates=document.lanes.Where(e=>!e.disabled&&e.fromNode==l.toNode&&e.turn==t&&e.change==0).Select(e=>e.id);l.next=v?l.next.Concat(candidates).Distinct().ToArray():l.next.Where(id=>!candidates.Contains(id)).ToArray();});}
  Caption("유턴: 관찰 메모만 지원");ActionButton("선택 차로ID 복사",()=>GUIUtility.systemCopyBuffer=l.id);Text("새 연결 대상 차로ID",connectTarget,v=>connectTarget=v);Number("새 연결 회전 -1/0/1",connectTurn,v=>connectTurn=(int)v,-1,1);Number("차로변경 방향 -1/0/1",connectChange,v=>connectChange=(int)v,-1,1);ActionButton("출구 연결 곡선 생성",()=>Edit(()=>Connect(l,connectTarget,connectTurn,connectChange)));if(SelectedPoint>0&&SelectedPoint<l.points.Length-1)ActionButton("선택점에서 차로 분할 (변경구간 시작)",()=>Edit(()=>SplitLane(l,SelectedPoint)));Caption("출구/차로변경 연결 (동일 끝점)");foreach(var edge in document.lanes.Where(e=>!e.disabled&&e.fromNode==l.toNode).ToArray()){var target=edge;Toggle(Short(target.id)+(target.change!=0?" [차로변경]":""),l.next.Contains(target.id),v=>l.next=v?l.next.Concat(new[]{target.id}).Distinct().ToArray():l.next.Where(id=>id!=target.id).ToArray());}
  ActionButton("선택점 중간에 제어점 추가",()=>Edit(()=>{int i=Mathf.Clamp(SelectedPoint,0,l.points.Length-2);NormalizeHeights(l);var heights=l.heights.ToList();heights.Insert(i+1,(heights[i]+heights[i+1])*.5f);l.heights=heights.ToArray();var list=l.points.ToList();var p=(list[i].V()+list[i+1].V())*.5f;list.Insert(i+1,new MapPoint{x=p.x,z=p.z});l.points=list.ToArray();SelectedPoint=i+1;}));if(l.points.Length>2&&SelectedPoint>0&&SelectedPoint<l.points.Length-1)ActionButton("선택 제어점 삭제",()=>Edit(()=>{NormalizeHeights(l);l.heights=l.heights.Where((h,i)=>i!=SelectedPoint).ToArray();l.points=l.points.Where((p,i)=>i!=SelectedPoint).ToArray();SelectedPoint=0;}));
  SelectedPoint=Mathf.Clamp(SelectedPoint,0,l.points.Length-1);Number("선택점 높이 m (지면=0)",l.heights!=null&&SelectedPoint<l.heights.Length?l.heights[SelectedPoint]:0,v=>SetHeight(l,SelectedPoint,v),0,1.5f);Number("선택점 X",l.points[SelectedPoint].x,v=>MovePoint(l,SelectedPoint,new Vector3(v,0,l.points[SelectedPoint].z)),0,session.world.map.width);Number("선택점 Z",l.points[SelectedPoint].z,v=>MovePoint(l,SelectedPoint,new Vector3(l.points[SelectedPoint].x,0,v)),0,session.world.map.depth);
  ActionButton("평행 차로 추가 (오른쪽 3.5m)",()=>Edit(()=>DuplicateLane(l)));
  ActionButton("짧은 좌회전 대기차로 추가",()=>Edit(()=>Pocket(l)));
  ActionButton("삭제 영향 확인",()=>deleteId=l.id);if(deleteId==l.id){int incoming=document.lanes.Count(n=>n.next.Contains(l.id));int refs=document.facilities.Count(f=>f.laneId==l.id)+document.signals.Sum(p=>p.groups.Count(g=>g.laneIds.Contains(l.id)));Caption("들어오는 연결 "+incoming+" / 시설·신호 참조 "+refs+" · 승하차 접근은 검사에서 차단");ActionButton("차로 비활성화 + 연결/종속 시설 제거",()=>Edit(()=>{l.disabled=true;l.next=new string[0];foreach(var n in document.lanes)n.next=n.next.Where(id=>id!=l.id).ToArray();var removed=document.facilities.Where(f=>f.laneId==l.id).Select(f=>f.id).ToArray();document.facilities=document.facilities.Where(f=>f.laneId!=l.id&&!removed.Contains(f.targetId)).ToArray();foreach(var p in document.signals)foreach(var g in p.groups)g.laneIds=g.laneIds.Where(id=>id!=l.id).ToArray();deleteId="";}));}
  Evidence(l.evidence);
 }
 void Connect(RoadMapLane from,string targetId,int turn,int change){var target=document.lanes.FirstOrDefault(x=>x.id==targetId&&!x.disabled);if(target==null||target==from){notice="다른 유효한 대상 차로ID를 입력하세요";return;}var a=from.points.Last().V();var b=target.points[0].V();var forward=(a-from.points[from.points.Length-2].V()).normalized;var heading=(target.points[1].V()-b).normalized;float handle=Vector3.Distance(a,b)*.4f;var pts=new MapPoint[33];for(int i=0;i<pts.Length;i++){float t=i/32f,u=1-t;var p=u*u*u*a+3*u*u*t*(a+forward*handle)+3*u*t*t*(b-heading*handle)+t*t*t*b;pts[i]=new MapPoint{x=p.x,z=p.z};}var join=new RoadMapLane{id="join:editor:"+Guid.NewGuid().ToString("N"),sourceId=from.sourceId,fromNode=from.toNode,toNode=target.fromNode,ruleId=from.ruleId,number=target.number,turn=turn,change=change,points=pts,next=new[]{target.id},status="provisional",width=from.width};document.lanes=document.lanes.Concat(new[]{join}).ToArray();from.next=from.next.Concat(new[]{join.id}).Distinct().ToArray();notice="연결 곡선 생성 · 검사로 진행/곡률 확인";} void SplitLane(RoadMapLane l,int at){NormalizeHeights(l);var tail=JsonUtility.FromJson<RoadMapLane>(JsonUtility.ToJson(l));string node="editor:split:"+Guid.NewGuid().ToString("N");tail.id="editor:tail:"+Guid.NewGuid().ToString("N");tail.fromNode=node;tail.points=l.points.Skip(at).ToArray();tail.heights=l.heights.Skip(at).ToArray();l.heights=l.heights.Take(at+1).ToArray();tail.sourceOffset+=new AssistedRoadNetwork.Path(l.points.Take(at+1).Select(p=>p.V()).ToArray()).length;l.points=l.points.Take(at+1).ToArray();l.toNode=node;l.next=new[]{tail.id};document.lanes=document.lanes.Concat(new[]{tail}).ToArray();SelectedPoint=l.points.Length-1;} static float Height(RoadMapLane l,int i){return l.heights!=null&&i<l.heights.Length?l.heights[i]:0;}static void NormalizeHeights(RoadMapLane l){if(l.heights==null||l.heights.Length!=l.points.Length)Array.Resize(ref l.heights,l.points.Length);} void SetHeight(RoadMapLane lane,int index,float value){string node=index==0?lane.fromNode:index==lane.points.Length-1?lane.toNode:null;foreach(var l in document.lanes){if(l.heights==null||l.heights.Length!=l.points.Length)Array.Resize(ref l.heights,l.points.Length);if(l==lane)l.heights[index]=value;if(node!=null&&l.fromNode==node)l.heights[0]=value;if(node!=null&&l.toNode==node)l.heights[l.heights.Length-1]=value;}} void DuplicateLane(RoadMapLane l){var copy=JsonUtility.FromJson<RoadMapLane>(JsonUtility.ToJson(l));string token=Guid.NewGuid().ToString("N");copy.id="editor:"+token;copy.fromNode="editor:start:"+token;copy.toNode="editor:end:"+token;copy.number=l.number+1;copy.next=new string[0];copy.status="provisional";NormalizeHeights(copy);for(int i=0;i<copy.points.Length;i++){var dir=(l.points[Mathf.Min(l.points.Length-1,i+1)].V()-l.points[Mathf.Max(0,i-1)].V()).normalized;var pos=copy.points[i].V()+TrafficSystem.Right(dir)*l.width;copy.points[i]=new MapPoint{x=pos.x,z=pos.z};}var additions=new List<RoadMapLane>{copy};foreach(string id in l.next){var old=document.lanes.First(e=>e.id==id);var join=JsonUtility.FromJson<RoadMapLane>(JsonUtility.ToJson(old));join.id="join:editor:"+Guid.NewGuid().ToString("N");join.fromNode=copy.toNode;join.points=Curve(copy.points.Last().V(),old.points[0].V(),old.points.Last().V());join.heights=new float[join.points.Length];copy.next=copy.next.Concat(new[]{join.id}).ToArray();additions.Add(join);}document.lanes=document.lanes.Concat(additions).ToArray();selected=copy.id;notice="평행 차로 생성 · 진입 연결은 별도 연결 도구로 지정하세요";}
 MapPoint[] Curve(Vector3 start,Vector3 mid,Vector3 end){var points=new MapPoint[17];for(int i=0;i<points.Length;i++){float t=i/16f;var p=(1-t)*(1-t)*start+2*(1-t)*t*mid+t*t*end;points[i]=new MapPoint{x=p.x,z=p.z};}return points;}
 void Pocket(RoadMapLane l){var path=new AssistedRoadNetwork.Path(l.points.Select(p=>p.V()).ToArray());if(path.length<65){notice="대기차로에는 65m 이상 차로가 필요합니다";return;}var left=l.next.Select(id=>document.lanes.First(e=>e.id==id)).FirstOrDefault(e=>e.turn<0);if(left==null){notice="기존 좌회전 출구가 필요합니다";return;}var source=JsonUtility.FromJson<RoadMapLane>(JsonUtility.ToJson(l));float cut=path.length-55;string token=Guid.NewGuid().ToString("N");string split="editor:split:"+token;var tail=JsonUtility.FromJson<RoadMapLane>(JsonUtility.ToJson(l));tail.id="editor:tail:"+token;tail.fromNode=split;tail.points=Slice(path,cut,path.length);tail.heights=tail.points.Select(p=>p.elevation).ToArray();tail.sourceOffset+=cut;l.points=Slice(path,0,cut);l.heights=l.points.Select(p=>p.elevation).ToArray();l.toNode=split;
  var pocket=JsonUtility.FromJson<RoadMapLane>(JsonUtility.ToJson(source));pocket.id="editor:pocket:"+token;pocket.fromNode=split;pocket.toNode="editor:pocket:end:"+token;pocket.number=1;pocket.status="provisional";var points=new List<MapPoint>();for(float at=cut;at<path.length;at+=1){float t=Mathf.Clamp01((at-cut)/25);var p=path.Position(at)-TrafficSystem.Right(path.Tangent(at))*l.width*t*t*(3-2*t);points.Add(new MapPoint{x=p.x,z=p.z});}var end=path.Position(path.length)-TrafficSystem.Right(path.Tangent(path.length))*l.width;points.Add(new MapPoint{x=end.x,z=end.z});pocket.points=points.ToArray();pocket.heights=new float[pocket.points.Length];var join=JsonUtility.FromJson<RoadMapLane>(JsonUtility.ToJson(left));join.id="join:editor:pocket:"+token;join.fromNode=pocket.toNode;join.points=Curve(end,left.points[0].V(),left.points.Last().V());join.heights=new float[join.points.Length];pocket.next=new[]{join.id};l.next=new[]{tail.id,pocket.id};document.lanes=document.lanes.Concat(new[]{tail,pocket,join}).ToArray();selected=pocket.id;notice="55m 대기차로 생성 (벌어짐25m) · 제어점으로 길이 조정 · 검사 필요";
 }
 static MapPoint[] Slice(AssistedRoadNetwork.Path path,float a,float b){var points=new List<MapPoint>();for(float d=a;d<b;d+=2){var p=path.Position(d);points.Add(new MapPoint{x=p.x,z=p.z});}var last=path.Position(b);points.Add(new MapPoint{x=last.x,z=last.z});return points.ToArray();}
 void AddFacility(string kind){Edit(()=>{var f=new RoadMapFacility{id="facility:"+Guid.NewGuid().ToString("N"),kind=kind,x=Centre.x,z=Centre.y,junctionId=junction,laneId=Lane==null?"":Lane.id,width=kind=="stopLine"?3.5f:3,length=kind=="stopLine"?.4f:2.4f};document.facilities=document.facilities.Concat(new[]{f}).ToArray();selected=f.id;});}
 void FacilityProperties(){var f=Facility;Caption(f.id);if(f.kind=="sign"){foreach(var type in new[]{"제한속도","좌회전 금지","우회전 금지","진입 금지","일방통행","비보호 좌회전","횡단보도","보호구역","방향 안내"}){string t=type;ActionButton((f.type==t?"● ":"")+t,()=>Edit(()=>f.type=t));}Text("표지 문구",f.text,v=>f.text=v);bool supported=f.type=="좌회전 금지"||f.type=="우회전 금지"||f.type=="진입 금지"||f.type=="제한속도";if(supported)Toggle("게임 규칙 적용",f.rule,v=>f.rule=v);else Caption("안내용 · 규칙 적용 미지원");Number("제한속도 km/h",f.speed,v=>f.speed=v,5,100);Number("적용 시작 m",f.startAt,v=>f.startAt=v,0,10000);Number("적용 끝 m",f.endAt,v=>f.endAt=v,0,10000);}
  Number("위치 X",f.x,v=>f.x=v,0,session.world.map.width);Number("위치 Z",f.z,v=>f.z=v,0,session.world.map.depth);Number("높이 m",f.height,v=>f.height=v,0,12);Number("방향 °",f.yaw,v=>f.yaw=v,-360,360);Number("폭 m",f.width,v=>f.width=v,.1f,40);Number("길이 m",f.length,v=>f.length=v,.1f,40);Number("배율",f.scale,v=>f.scale=v,.1f,5);Text("적용 차로ID",f.laneId,v=>f.laneId=v);Text("교차로ID",f.junctionId,v=>f.junctionId=v);Number("접근 축 0/1",f.axis,v=>f.axis=(int)v,0,1);Number("접근 방향 +1/-1",f.sign,v=>f.sign=v<0?-1:1,-1,1);
  if(f.kind.Contains("Signal")){Text("신호 그룹ID",f.groupId,v=>f.groupId=v);Text("제어 정지선/횡단보도ID",f.targetId,v=>f.targetId=v);}
  ActionButton("지면/선택 차로 끝 가장자리에 맞춤",()=>Edit(()=>{var l=document.lanes.FirstOrDefault(e=>e.id==f.laneId);if(l==null)return;var p=l.points.Last().V();var dir=(p-l.points[l.points.Length-2].V()).normalized;p+=TrafficSystem.Right(dir)*(l.width*.5f+1);f.x=p.x;f.z=p.z;f.yaw=Quaternion.LookRotation(dir).eulerAngles.y;}));ActionButton("시설 ID 복사",()=>GUIUtility.systemCopyBuffer=f.id);ActionButton("시설 삭제 (연결 대상은 검사 필요)",()=>Edit(()=>{document.facilities=document.facilities.Where(x=>x.id!=f.id).ToArray();selected="";}));Evidence(f.evidence);
 }
 void Evidence(RoadMapEvidence e){if(e==null)return;Caption("근거 · 미확인은 게임 설정");foreach(var state in new[]{"game","estimated","observed"}){string s=state;ActionButton((e.state==s?"● ":"")+s,()=>Edit(()=>e.state=s));}Text("거리뷰 URL",e.url,v=>e.url=v);Text("촬영월 YYYY-MM",e.month,v=>e.month=v);Text("확인일 YYYY-MM-DD",e.checkedAt,v=>e.checkedAt=v);Toggle("외형 확인",e.appearanceConfirmed,v=>e.appearanceConfirmed=v);Toggle("규칙 확인",e.ruleConfirmed,v=>e.ruleConfirmed=v);Text("메모 / 유턴 관찰",e.note,v=>e.note=v);}
 void SignalProperties(){var program=document.signals.FirstOrDefault(p=>p.junctionId==junction);if(program==null){ActionButton("기존 신호 가져오기 / 그룹 편집 시작",()=>{var j=session.traffic.junctions.FirstOrDefault(x=>x.name==junction);if(j==null){notice="선택 교차로에는 가져올 신호가 없습니다";return;}Edit(()=>{var p=RoadMapSignalProgram.Import(session.traffic,j);document.signals=document.signals.Concat(new[]{p}).ToArray();ImportSignalFacilities(j,p);});});Caption("신호기를 선택하면 위치/제어 대상을 아래에서 편집합니다.");}else{
   Caption("게임 신호 순서표 · "+junction);ActionButton("신호 편집 원상 복원",()=>Edit(()=>{document.signals=document.signals.Where(p=>p!=program).ToArray();document.facilities=document.facilities.Where(f=>f.junctionId!=junction||!f.kind.Contains("Signal")).ToArray();}));
   foreach(var stage in program.stages){Caption("― "+stage.name+" ―");Text("단계명 "+stage.GetHashCode(),stage.name,v=>stage.name=v);Number(stage.name+" 녹색초",stage.green,v=>stage.green=v,1,120);Number(stage.name+" 황색초",stage.yellow,v=>stage.yellow=v,0,10);Number(stage.name+" 정리초",stage.clearance,v=>stage.clearance=v,1,30);foreach(var g in program.groups){var group=g;Toggle(group.name,stage.groups.Contains(g.id),v=>stage.groups=v?stage.groups.Concat(new[]{group.id}).Distinct().ToArray():stage.groups.Where(id=>id!=group.id).ToArray());}ActionButton("이 단계 삭제",()=>Edit(()=>program.stages=program.stages.Where(s=>s!=stage).ToArray()));}
   ActionButton("빈 단계 추가",()=>Edit(()=>program.stages=program.stages.Concat(new[]{new RoadMapStage{name="새 단계 "+(program.stages.Length+1)}}).ToArray()));
   Caption("그룹 · 함께 켜질 진행/보행");foreach(var g in program.groups){var group=g;Caption(group.name);if(g.pedestrian)Text("횡단보도ID "+g.id,g.crosswalkId,v=>g.crosswalkId=v);ActionButton("그룹ID 복사",()=>GUIUtility.systemCopyBuffer=group.id);Text("차로ID 목록 (쉼표) "+g.id,string.Join(",",g.laneIds),v=>g.laneIds=v.Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).Select(s=>s.Trim()).ToArray());Number("축 "+g.id,g.axis,v=>g.axis=(int)v,0,1);Number("방향 "+g.id,g.sign,v=>g.sign=v<0?-1:1,-1,1);Number("회전 -1/0/1 "+g.id,g.turn,v=>g.turn=(int)v,-1,1);}
   ActionButton("차량 그룹 추가",()=>Edit(()=>program.groups=program.groups.Concat(new[]{new RoadMapSignalGroup{name="새 차량 그룹"}}).ToArray()));ActionButton("보행 그룹 추가",()=>Edit(()=>program.groups=program.groups.Concat(new[]{new RoadMapSignalGroup{name="새 보행 그룹",pedestrian=true}}).ToArray()));
  }
  if(Facility!=null)FacilityProperties();ActionButton("차량 신호기 추가",()=>AddFacility("vehicleSignal"));ActionButton("보행 신호기 추가",()=>AddFacility("pedestrianSignal"));
 }
 void ImportSignalFacilities(TrafficJunction j,RoadMapSignalProgram program){var facilities=document.facilities.ToList();foreach(var g in program.groups){var dir=session.traffic.AxisDirection(j,g.axis)*g.sign;float distance=j.StopDistance(g.axis);string kind=g.pedestrian?"crosswalk":"stopLine";var mark=facilities.FirstOrDefault(f=>f.junctionId==j.name&&f.kind==kind&&f.axis==g.axis&&f.sign==g.sign);if(mark==null){var pos=j.center-dir*(g.pedestrian?j.halfWidth[1-g.axis]+TrafficJunction.CrosswalkCentreOffset:distance);mark=new RoadMapFacility{id="facility:"+Guid.NewGuid().ToString("N"),kind=kind,junctionId=j.name,axis=g.axis,sign=g.sign,x=pos.x,z=pos.z,yaw=Quaternion.LookRotation(dir).eulerAngles.y,width=g.pedestrian?j.halfWidth[g.axis]*2:j.halfWidth[g.axis],length=g.pedestrian?2.4f:.4f};facilities.Add(mark);}var p=j.center+dir*distance+TrafficSystem.Right(dir)*(j.halfWidth[g.axis]+1);facilities.Add(new RoadMapFacility{id="facility:"+Guid.NewGuid().ToString("N"),kind=g.pedestrian?"pedestrianSignal":"vehicleSignal",junctionId=j.name,axis=g.axis,sign=g.sign,x=p.x,z=p.z,yaw=Quaternion.LookRotation(dir).eulerAngles.y,groupId=g.id,targetId=mark.id,text=g.name});if(g.pedestrian)g.crosswalkId=mark.id;}document.facilities=facilities.ToArray();}
}
